// Kindermodus/Intents/KidModeIntents.swift
import AppIntents
import FamilyControls

struct ChildEntity: AppEntity {
    static var typeDisplayRepresentation = TypeDisplayRepresentation(name: "Kind")
    var id: UUID; var name: String
    var displayRepresentation: DisplayRepresentation { .init(title: "\(name)") }

    struct Query: EntityQuery {
        func entities(for ids: [UUID]) async throws -> [ChildEntity] {
            try await suggestedEntities().filter { ids.contains($0.id) }
        }
        func suggestedEntities() async throws -> [ChildEntity] {
            let profiles = SharedStore.shared.load([ChildProfile].self, from: KMKeys.profiles) ?? []
            return profiles.map { ChildEntity(id: $0.id, name: $0.name) }
        }
    }
    static var defaultQuery = Query()
}

// 🔒 "Hey Siri, Kindermodus an." — safe direction, zero auth friction.
struct KidModeOnIntent: AppIntent {
    static var title: LocalizedStringResource = "Kindermodus aktivieren"
    static var description = IntentDescription("Sperrt das Gerät sofort für die gewählten Kinder.")
    static var openAppWhenRun = false

    @Parameter(title: "Kind") var child: ChildEntity?   // nil = alle drei

    func perform() async throws -> some IntentResult & ProvidesDialog {
        let all = SharedStore.shared.load([ChildProfile].self, from: KMKeys.profiles) ?? []
        let chosen = child.map { c in all.filter { $0.id == c.id } } ?? all
        guard !chosen.isEmpty else { return .result(dialog: "Keine Kinderprofile gefunden.") }
        try? KMEngine.shared.startKidMode(for: chosen)      // local — instant
        let names = chosen.map(\.name).joined(separator: ", ")
        return .result(dialog: "Kindermodus aktiviert für \(names). 📵")
    }
}

// 🍽️ "Hey Siri, Mittagssperre." — locks and auto-releases.
struct LunchLockIntent: AppIntent {
    static var title: LocalizedStringResource = "Mittags-Sperre aktivieren"
    static var openAppWhenRun = false
    @Parameter(title: "Minuten", default: 60) var minutes: Int

    func perform() async throws -> some IntentResult & ProvidesDialog {
        let all = SharedStore.shared.load([ChildProfile].self, from: KMKeys.profiles) ?? []
        try? KMEngine.shared.lunchLock(profiles: all, minutes: minutes)
        return .result(dialog: "Mittags-Sperre aktiv für \(minutes) Minuten. Guten Appetit!")
    }
}

// 🔓 THE DANGEROUS ONE — "Siri, Kindermodus aus." said by a kid must ALWAYS fail.
struct KidModeOffIntent: AppIntent {
    static var title: LocalizedStringResource = "Kindermodus beenden"

    /// ⭐ Factor 1: fresh Face ID / device passcode scan on EVERY run — even though the
    ///    kid often holds an already-unlocked phone. Dad's face passes; Leandro's doesn't.
    static var authenticationPolicy: IntentAuthenticationPolicy {
        .alwaysRequiresLocalDeviceAuthentication
    }
    /// ⭐ Factor 2: even a passed Face ID doesn't unlock directly — the app opens into
    ///    the ParentGate PIN. Face ID convenience ≠ authorization.
    static var openAppWhenRun = true

    func perform() async throws -> some IntentResult & ProvidesDialog {
        // Stage only. Locks remain until ParentGate succeeds (see Phase-4 gate code).
        SharedStore.shared.defaults.set(true, forKey: KMKeys.pendingGate)
        return .result(dialog: "Zum Entsperren bitte die Eltern-PIN eingeben.")
    }
}

